function showTemplates(){$('templateList').innerHTML=templates.length?templates.map(t=>`<div class="template-row"><div><h3>${e(t.name)}</h3><p>${t.budget.items.length} postes · salaire net ${money(t.budget.netDayRate)} / jour · majoration ${number(t.budget.markupPct)} %</p></div><div class="toolbar"><button class="button secondary" data-action="use-template" data-id="${e(t.id)}">Utiliser</button><button class="text-button" data-action="export-template" data-id="${e(t.id)}">Exporter</button><button class="text-button" data-action="delete-template" data-id="${e(t.id)}">Retirer</button></div></div>`).join(''):'<div class="empty">Enregistrez votre budget actuel ou importez un modèle existant.</div>';if(!$('templatesDialog').open)$('templatesDialog').showModal();}
function applyTemplate(t){if(!confirm('Remplacer les hypothèses du budget de référence par ce modèle ? Les dates de référence, les tarifs vendus et les budgets initiaux figés seront conservés.'))return false;const okay=mutate(next=>{const dates={startDate:next.budget.startDate,endDate:next.budget.endDate,daysOverride:next.budget.daysOverride,offDays:next.budget.offDays,extraDays:next.budget.extraDays};next.budget={...E.copy(t.budget),...dates};const ids=new Set(next.categories.map(c=>c.id));next.categories.push(...t.categories.filter(c=>!ids.has(c.id)).map(E.copy));next.salaryCategoryId=t.salaryCategoryId||'salaries';},'Modèle appliqué au budget. Les copies personnalisées et les références figées sont conservées.');if(okay){$('templatesDialog').close();nav('budget');}return okay;}
function importedTemplate(value){let t;if(value?.type==='marge-cost-model'&&validCostModel(value.model))t={id:E.uuid(),name:value.model.name,budget:E.budgetFromModel(value.model),categories:E.copy(E.DEFAULT_CATEGORIES),salaryCategoryId:'salaries'};else if(value?.type==='marge-budget-template'&&value.template)t={...E.copy(value.template),id:E.uuid()};else if(validCostModel(value))t={id:E.uuid(),name:value.name,budget:E.budgetFromModel(value),categories:E.copy(E.DEFAULT_CATEGORIES),salaryCategoryId:'salaries'};if(!templateValid(t))throw new Error('Le fichier ne contient pas un modèle de budget compatible.');if(!saveTemplates([t,...templates]))return;showTemplates();toast('Modèle importé. Cliquez sur Utiliser pour l’appliquer au budget de référence.');}
async function importModelLink(){const compressed=location.hash.startsWith('#modeleGzip='),plain=location.hash.startsWith('#modele=');if(!compressed&&!plain)return;try{const payload=location.hash.slice(compressed?12:8);history.replaceState(null,'',location.pathname+location.search+'#budget');if(payload.length>100000)throw new Error('Lien trop long.');let bytes=Uint8Array.from(atob(payload.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0));if(compressed){const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')).getReader(),parts=[];let size=0;while(true){const part=await reader.read();if(part.done)break;size+=part.value.length;if(size>200000){await reader.cancel();throw new Error('Modèle trop volumineux.');}parts.push(part.value);}bytes=new Uint8Array(size);let offset=0;for(const part of parts){bytes.set(part,offset);offset+=part.length;}}importedTemplate(JSON.parse(new TextDecoder().decode(bytes)));}catch(error){toast('Import du modèle impossible : '+error.message);}}
